"""Small standard-library implementation of lla's content-search view."""
import os
import re
from pathlib import Path
try:
    from filters import matches_name
except ImportError:
    matches_name = None


def search_text(root, query, context=2, case_sensitive=False, file_filter=None):
    """Return the human-readable search output for a directory search.

    Returns an empty string when no text matches. The caller handles --json and
    --csv separately because the reference emits ripgrep's streaming JSON for
    those modes (including nondeterministic timing fields).
    """
    root = Path(root)
    if root.is_file():
        return "✗ Error\n\n  Failed to run ripgrep: Not a directory (os error 20)\n"
    if not root.is_dir():
        return "✗ Error\n\n  Failed to run ripgrep: No such file or directory (os error 2)\n"
    if query.startswith("regex:"):
        pattern = query[6:]
        try:
            rx = re.compile(pattern, 0 if case_sensitive else re.I)
        except re.error:
            return ""
        match = lambda s: list(rx.finditer(s))
    else:
        needle = query if case_sensitive else query.casefold()
        def match(s):
            hay = s if case_sensitive else s.casefold()
            out = []
            start = 0
            while needle and (pos := hay.find(needle, start)) >= 0:
                out.append((pos, pos + len(query)))
                start = pos + max(1, len(query))
            return out

    try:
        context = max(0, int(context))
    except (TypeError, ValueError):
        context = 2
    blocks = []
    for base, dirs, files in os.walk(root):
        dirs[:] = sorted(d for d in dirs if not d.startswith(".") and d != ".git")
        for name in sorted(files):
            if name.startswith("."):
                continue
            path = Path(base) / name
            if file_filter and not (matches_name(name, file_filter, case_sensitive) if matches_name else file_filter.casefold() in name.casefold()):
                continue
            try:
                data = path.read_bytes()
                if b"\0" in data[:8192]:
                    continue
                lines = data.decode("utf-8", "replace").splitlines()
            except OSError:
                continue
            matches = {}
            for i, line in enumerate(lines):
                found = match(line)
                if found:
                    matches[i] = found
            if not matches:
                continue
            selected = set()
            for i in matches:
                selected.update(range(max(0, i-context), min(len(lines), i+context+1)))
            # Keep disjoint context regions separated, as ripgrep does.
            rel = os.path.relpath(path, root)
            rows = [f"\nFile: {rel} [{path}]"]
            prev = -2
            for i in sorted(selected):
                if prev >= 0 and i > prev + 1:
                    rows.append("")
                row = f"{i+1:4d} │ {lines[i]}"
                rows.append(row)
                if i in matches:
                    spans = matches[i]
                    marker = [" "] * len(lines[i])
                    for span in spans:
                        a, b = (span.start(), span.end()) if hasattr(span, "start") else span
                        for j in range(max(0, a), min(len(marker), max(a+1, b))):
                            marker[j] = "^"
                    rows.append(f"{i+1:4d} │ {''.join(marker)}")
                prev = i
            blocks.append("\n".join(rows))
    return "\n".join(blocks) + ("\n" if blocks else "")
