"""Box-drawn table renderer for lla listings."""
import datetime
import os
import stat


def _permissions(e, style):
    try:
        mode = stat.filemode(os.lstat(e['path']).st_mode)
    except OSError:
        mode = '----------'
    if style == 'octal':
        return mode[0] + e.get('mode_octal', '0000')[-3:]
    if style == 'compact':
        return e.get('mode_octal', '0000')[-3:]
    if style == 'binary':
        return mode[0] + format(stat.S_IMODE(os.lstat(e['path']).st_mode), '09b')
    if style == 'verbose':
        p = mode[1:]
        return f"type:{e['file_type']} owner:{p[:3]} group:{p[3:6]} others:{p[6:9]}"
    # The reference's symbolic formatter repeats the permission value in its
    # default column rendering; preserve that visible behavior.
    if style == 'symbolic':
        return mode[0] + mode * 3
    if style == 'compact':
        return e.get('mode_octal', '0000')[-3:]
    return mode


def _size(n):
    if n < 1024:
        return f'{n}B'
    if n < 1024**2:
        return f'{n/1024:.1f}K'
    if n < 1024**3:
        return f'{n/(1024**2):.1f}M'
    return f'{n/(1024**3):.1f}G'


def render_table(entries, permission_format='symbolic', hide_group=False):
    cols = [('Permissions', lambda e: _permissions(e, permission_format)),
            ('Size', lambda e: _size(e['size_bytes'])),
            ('Modified', lambda e: datetime.datetime.fromisoformat(e['modified'].replace('Z', '+00:00')).astimezone().strftime('%b %d %H:%M')),
            ('Name', lambda e: e['name'] + ('/' if e['file_type'] == 'dir' else ''))]
    vals = [[fn(e) for _, fn in cols] for e in entries]
    widths = [max([len(cols[i][0])] + [len(row[i]) for row in vals]) for i in range(len(cols))]
    def border(left, mid, right):
        return left + mid.join('─' * (w + 2) for w in widths) + right
    out = [border('┌', '┬', '┐')]
    out.append('│' + '│'.join(' ' + cols[i][0].ljust(widths[i]) + ' ' for i in range(len(cols))) + '│')
    out.append(border('├', '┼', '┤'))
    for row in vals:
        out.append('│' + '│'.join(' ' + (row[i].rjust(widths[i]) if i == 1 else row[i].ljust(widths[i])) + ' ' for i in range(len(cols))) + '│')
    out.append(border('└', '┴', '┘'))
    return '\n'.join(out) + '\n\n'
